WITH with_gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS session_start_flag FROM web_events), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id_2 FROM with_gaps) SELECT s.id, s.session_id, s.event_type, s.page, s.event_time, s.duration_sec, s.session_start_flag, s.session_id_2, (SELECT SUM(t2.duration_sec) FROM web_events t2 WHERE t2.session_id = s.session_id) AS sum_web_event_duration_sec FROM sessionized s ORDER BY session_id DESC NULLS FIRST
